1	package meter
2	
3	import (
4		"errors"
5		"testing"
6	)
7	
8	// 本文件回归“付款标识只在所属账户内去重”。
9	//
10	// 付款标识的去重域是单个账户：同一个服务中不同账户对各自账期相同的账单
11	// 使用同一个付款标识，必须分别作为首次付款接受，互不干扰——即使两笔金额
12	// 不同、且两张账单都已过付款截止时刻。同时账户内的既有边界不能被破坏：
13	// 同标识改金额或改账期仍是本账户的冲突；原样重报只返回本账户首次登记时
14	// 的历史结果，不改变任何账户账单与停用状态的当前值。
15	//
16	// 场景：两个各有一份已生效订阅的账户 a、b，2026-01 账单应付分别为
17	// 1000 分与 2000 分（税额、用量均为零），付款截止时刻均为 2026-02-08。
18	// 当前时钟已到截止时刻，两账户都因欠费停用，订阅仍有效。
19	
20	// multiAccountPaymentFixture 构造上述两个账户及其一月账单，并把时钟拨到
21	// 2026-02-08 00:00（恰好到达付款截止时刻），两账户均处于欠费停用状态。
22	func multiAccountPaymentFixture(t *testing.T) (*Service, *fakeClock) {
23		t.Helper()
24		s, clk := newTestService(utc(2026, 1, 1, 0, 0))
25		mustPlan(t, s, Plan{ID: "plan1000", MonthlyFee: 1000, IncludedUnits: 0, OveragePrice: 0, TaxRateBasisPoints: 0})
26		mustPlan(t, s, Plan{ID: "plan2000", MonthlyFee: 2000, IncludedUnits: 0, OveragePrice: 0, TaxRateBasisPoints: 0})
27		mustAccount(t, s, "a")
28		mustAccount(t, s, "b")
29		if err := s.Subscribe("a", "plan1000", utc(2026, 1, 1, 0, 0)); err != nil {
30			t.Fatalf("subscribe a: %v", err)
31		}
32		if err := s.Subscribe("b", "plan2000", utc(2026, 1, 1, 0, 0)); err != nil {
33			t.Fatalf("subscribe b: %v", err)
34		}
35	
36		clk.t = utc(2026, 2, 8, 0, 0)
37		ba, err := s.CreateBill("a", jan(2026))
38		if err != nil {
39			t.Fatalf("create bill a: %v", err)
40		}
41		if ba.TotalDue != 1000 || ba.Paid != 0 || ba.Balance != 1000 || ba.Settled || ba.Tax != 0 || ba.TotalUsage != 0 {
42			t.Fatalf("bill a initial state: %+v", ba)
43		}
44		bb, err := s.CreateBill("b", jan(2026))
45		if err != nil {
46			t.Fatalf("create bill b: %v", err)
47		}
48		if bb.TotalDue != 2000 || bb.Paid != 0 || bb.Balance != 2000 || bb.Settled || bb.Tax != 0 || bb.TotalUsage != 0 {
49			t.Fatalf("bill b initial state: %+v", bb)
50		}
51		return s, clk
52	}
53	
54	// wantAccountBillState 校验一个账户一月账单的当前付款状态，并保证付款操作
55	// 不改变出账时即固定的应付总额、税额与用量明细。
56	func wantAccountBillState(t *testing.T, s *Service, acct string, totalDue, paid, balance int64, settled bool) {
57		t.Helper()
58		b, err := s.GetBill(acct, jan(2026))
59		if err != nil {
60			t.Fatalf("get bill %q: %v", acct, err)
61		}
62		if b.TotalDue != totalDue || b.Paid != paid || b.Balance != balance || b.Settled != settled {
63			t.Fatalf("bill %q state: due=%d paid=%d balance=%d settled=%v, want due=%d paid=%d balance=%d settled=%v",
64				acct, b.TotalDue, b.Paid, b.Balance, b.Settled, totalDue, paid, balance, settled)
65		}
66		// 所有付款操作都只更新付款状态：应付总额、税额与用量保持出账时的值。
67		if b.MonthlyFee != totalDue || b.OverageFee != 0 || b.Tax != 0 {
68			t.Fatalf("bill %q amounts changed: %+v", acct, b)
69		}
70		if b.TotalUsage != 0 || b.IncludedUnits != 0 || b.OverageUnits != 0 {
71			t.Fatalf("bill %q usage detail changed: %+v", acct, b)
72		}
73	
74		st, err := s.Status(acct)
75		if err != nil {
76			t.Fatalf("status %q: %v", acct, err)
77		}
78		if len(st.Bills) != 1 {
79			t.Fatalf("status %q bills = %+v", acct, st.Bills)
80		}
81		bs := st.Bills[0]
82		if bs.Period != jan(2026) || bs.TotalDue != totalDue || bs.Paid != paid ||
83			bs.Balance != balance || bs.Settled != settled {
84			t.Fatalf("status %q bill summary = %+v, want due=%d paid=%d balance=%d settled=%v",
85				acct, bs, totalDue, paid, balance, settled)
86		}
87	}
88	
89	// wantAccountFlags 校验账户的停用状态：欠费停用与订阅是否生效分别表示。
90	func wantAccountFlags(t *testing.T, s *Service, acct string, suspended bool) AccountStatus {
91		t.Helper()
92		st, err := s.Status(acct)
93		if err != nil {
94			t.Fatalf("status %q: %v", acct, err)
95		}
96		if st.Suspended != suspended {
97			t.Fatalf("account %q suspended = %v, want %v; bills: %+v", acct, st.Suspended, suspended, st.Bills)
98		}
99		// 欠费停用不影响订阅本身：两段订阅在整个场景中始终有效。
100		if !st.Subscribed {
101			t.Fatalf("account %q subscription must remain active: %+v", acct, st)
102		}
103		return st
104	}
105	
106	// TestPaymentIDDedupScopedToAccount 覆盖跨账户复用同一付款标识的完整回归：
107	// 两账户各自的首次登记、状态独立性、补齐结清、历史重报与账户内冲突边界。
108	func TestPaymentIDDedupScopedToAccount(t *testing.T) {
109		s, clk := multiAccountPaymentFixture(t)
110		_ = clk
111	
112		janDue := utc(2026, 2, 8, 0, 0)
113	
114		// 起点：两账户都已到截止时刻、欠费停用，各自账单独立。
115		wantAccountFlags(t, s, "a", true)
116		wantAccountFlags(t, s, "b", true)
117		wantAccountBillState(t, s, "a", 1000, 0, 1000, false)
118		wantAccountBillState(t, s, "b", 2000, 0, 2000, false)
119	
120		// 账户 a 以共享标识 pay-shared 登记 400：首次登记成功，余额 600，未付清。
121		ra, err := s.RecordPayment("a", "pay-shared", jan(2026), 400)
122		if err != nil || !ra.Registered {
123			t.Fatalf("a pay-shared 400: r=%+v err=%v", ra, err)
124		}
125		if ra.Payment.AccountID != "a" || ra.Payment.PaymentID != "pay-shared" ||
126			ra.Payment.Period != jan(2026) || ra.Payment.Amount != 400 {
127			t.Fatalf("a first payment content: %+v", ra.Payment)
128		}
129		if ra.BillBalance != 600 || ra.Settled {
130			t.Fatalf("a first payment result: balance=%d settled=%v, want 600/false", ra.BillBalance, ra.Settled)
131		}
132	
133		// 账户 b 用完全相同的标识登记 500（账期相同、金额不同）：
134		// 必须作为 b 自己的首次付款接受，而不是重报（Registered 仍为 true），
135		// 也不能因为 a 已用过该标识而返回冲突。
136		rb, err := s.RecordPayment("b", "pay-shared", jan(2026), 500)
137		if err != nil {
138			t.Fatalf("b pay-shared 500 must be accepted as first payment: %v", err)
139		}
140		if !rb.Registered {
141			t.Fatalf("b pay-shared must register anew, got replay: %+v", rb)
142		}
143		if rb.Payment.AccountID != "b" || rb.Payment.PaymentID != "pay-shared" ||
144			rb.Payment.Period != jan(2026) || rb.Payment.Amount != 500 {
145			t.Fatalf("b first payment content: %+v", rb.Payment)
146		}
147		if rb.BillBalance != 1500 || rb.Settled {
148			t.Fatalf("b first payment result: balance=%d settled=%v, want 1500/false", rb.BillBalance, rb.Settled)
149		}
150	
151		// 两账户查询中的已付金额、余额、停用状态各自对应自己的账单；
152		// b 的成功登记不能影响 a 的记录，两账户都未付清、继续停用。
153		wantAccountBillState(t, s, "a", 1000, 400, 600, false)
154		wantAccountBillState(t, s, "b", 2000, 500, 1500, false)
155		wantAccountFlags(t, s, "a", true)
156		wantAccountFlags(t, s, "b", true)
157	
158		// 用另一标识为 a 补齐 600：a 已付清、停用解除；b 仍欠费停用。
159		topUp, err := s.RecordPayment("a", "pay-topup", jan(2026), 600)
160		if err != nil || !topUp.Registered || topUp.BillBalance != 0 || !topUp.Settled {
161			t.Fatalf("a top-up 600: r=%+v err=%v", topUp, err)
162		}
163		wantAccountBillState(t, s, "a", 1000, 1000, 0, true)
164		wantAccountBillState(t, s, "b", 2000, 500, 1500, false)
165		wantAccountFlags(t, s, "a", false)
166		wantAccountFlags(t, s, "b", true)
167	
168		// 此后原样重报前面的两笔：都成功但不再次登记，各自返回首次登记完成时
169		// 的历史结果——a 仍是余额 600、未付清；b 仍是余额 1500、未付清。
170		replayA, err := s.RecordPayment("a", "pay-shared", jan(2026), 400)
171		if err != nil {
172			t.Fatalf("replay a 400: %v", err)
173		}
174		if replayA.Registered || replayA.Payment.AccountID != "a" ||
175			replayA.BillBalance != 600 || replayA.Settled {
176			t.Fatalf("replay a historical result: %+v, want Registered=false balance=600 settled=false", replayA)
177		}
178		replayB, err := s.RecordPayment("b", "pay-shared", jan(2026), 500)
179		if err != nil {
180			t.Fatalf("replay b 500: %v", err)
181		}
182		if replayB.Registered || replayB.Payment.AccountID != "b" ||
183			replayB.BillBalance != 1500 || replayB.Settled {
184			t.Fatalf("replay b historical result: %+v, want Registered=false balance=1500 settled=false", replayB)
185		}
186	
187		// 历史付款结果不能替代账单查询与账户状态中的当前结果，也不能让 a 重新
188		// 停用：时钟仍停在截止时刻，a 当前已结清、未停用，b 当前仍欠费停用。
189		if !clk.t.Equal(janDue) {
190			t.Fatalf("clock moved unexpectedly: %v", clk.t)
191		}
192		wantAccountBillState(t, s, "a", 1000, 1000, 0, true)
193		wantAccountBillState(t, s, "b", 2000, 500, 1500, false)
194		wantAccountFlags(t, s, "a", false)
195		wantAccountFlags(t, s, "b", true)
196	
197		// 账户内冲突边界仍按各自账户独立裁决：已成功标识在 a 改金额，
198		// 或改指向尚未出账的另一月份，都按 a 的付款冲突拒绝。
199		if _, err := s.RecordPayment("a", "pay-shared", jan(2026), 401); !errors.Is(err, ErrPaymentConflict) {
200			t.Fatalf("a same id changed amount: %v", err)
201		}
202		if _, err := s.RecordPayment("a", "pay-shared", mar(2026), 400); !errors.Is(err, ErrPaymentConflict) {
203			t.Fatalf("a same id repointed to unbilled month: %v", err)
204		}
205		// b 对同一标识的冲突判定同样只看 b 自己的登记（金额 500、一月）：
206		// 改成 501 或指向未出账月份都是 b 的冲突，而不是命中 a 的记录。
207		if _, err := s.RecordPayment("b", "pay-shared", jan(2026), 501); !errors.Is(err, ErrPaymentConflict) {
208			t.Fatalf("b same id changed amount: %v", err)
209		}
210		if _, err := s.RecordPayment("b", "pay-shared", mar(2026), 500); !errors.Is(err, ErrPaymentConflict) {
211			t.Fatalf("b same id repointed to unbilled month: %v", err)
212		}
213		// a 的补齐标识同样保留账户内冲突边界。
214		if _, err := s.RecordPayment("a", "pay-topup", jan(2026), 1); !errors.Is(err, ErrPaymentConflict) {
215			t.Fatalf("a top-up id changed amount: %v", err)
216		}
217	
218		// 冲突拒绝不改变任何账户的已付金额、余额或停用状态。
219		wantAccountBillState(t, s, "a", 1000, 1000, 0, true)
220		wantAccountBillState(t, s, "b", 2000, 500, 1500, false)
221		wantAccountFlags(t, s, "a", false)
222		wantAccountFlags(t, s, "b", true)
223	
224		// b 用自己的新标识补齐剩余 1500：b 也结清并恢复，不影响 a。
225		finalB, err := s.RecordPayment("b", "pay-b-final", jan(2026), 1500)
226		if err != nil || !finalB.Registered || finalB.BillBalance != 0 || !finalB.Settled {
227			t.Fatalf("b final 1500: r=%+v err=%v", finalB, err)
228		}
229		wantAccountBillState(t, s, "a", 1000, 1000, 0, true)
230		wantAccountBillState(t, s, "b", 2000, 2000, 0, true)
231		wantAccountFlags(t, s, "a", false)
232		wantAccountFlags(t, s, "b", false)
233	
234		// 两账户都结清后重报共享标识，仍各自返回首次登记时的历史未付清结果。
235		replayA2, err := s.RecordPayment("a", "pay-shared", jan(2026), 400)
236		if err != nil || replayA2.Registered || replayA2.BillBalance != 600 || replayA2.Settled {
237			t.Fatalf("replay a after both settled: %+v err=%v", replayA2, err)
238		}
239		replayB2, err := s.RecordPayment("b", "pay-shared", jan(2026), 500)
240		if err != nil || replayB2.Registered || replayB2.BillBalance != 1500 || replayB2.Settled {
241			t.Fatalf("replay b after both settled: %+v err=%v", replayB2, err)
242		}
243		wantAccountBillState(t, s, "a", 1000, 1000, 0, true)
244		wantAccountBillState(t, s, "b", 2000, 2000, 0, true)
245	}
246	
247	// TestPaymentIDReusedAcrossAccountsConcurrent 并发版本：两个账户在同一时刻
248	// 用同一标识对各自账单登记付款。去重判定按账户各自的临界区独立进行，两笔
249	// 都必须首次登记成功，不能因为同服务中的并发碰撞而把其中一笔判成重报或
250	// 冲突，也不能把一笔的金额记到另一个账户的账单上。
251	func TestPaymentIDReusedAcrossAccountsConcurrent(t *testing.T) {
252		const rounds = 100
253		for iter := 0; iter < rounds; iter++ {
254			s, _ := newTestService(utc(2026, 2, 8, 0, 0))
255			mustPlan(t, s, Plan{ID: "plan1000", MonthlyFee: 1000, TaxRateBasisPoints: 0})
256			mustPlan(t, s, Plan{ID: "plan2000", MonthlyFee: 2000, TaxRateBasisPoints: 0})
257			a := "ca"
258			b := "cb"
259			mustAccount(t, s, a)
260			mustAccount(t, s, b)
261			if err := s.Subscribe(a, "plan1000", utc(2026, 1, 1, 0, 0)); err != nil {
262				t.Fatalf("iter %d subscribe a: %v", iter, err)
263			}
264			if err := s.Subscribe(b, "plan2000", utc(2026, 1, 1, 0, 0)); err != nil {
265				t.Fatalf("iter %d subscribe b: %v", iter, err)
266			}
267			if _, err := s.CreateBill(a, jan(2026)); err != nil {
268				t.Fatalf("iter %d bill a: %v", iter, err)
269			}
270			if _, err := s.CreateBill(b, jan(2026)); err != nil {
271				t.Fatalf("iter %d bill b: %v", iter, err)
272			}
273	
274			type res struct {
275				r   PaymentResult
276				err error
277			}
278			resA, resB := make(chan res, 1), make(chan res, 1)
279			start := make(chan struct{})
280			go func() {
281				<-start
282				r, err := s.RecordPayment(a, "shared", jan(2026), 400)
283				resA <- res{r, err}
284			}()
285			go func() {
286				<-start
287				r, err := s.RecordPayment(b, "shared", jan(2026), 500)
288				resB <- res{r, err}
289			}()
290			close(start)
291			ra := <-resA
292			rb := <-resB
293	
294			if ra.err != nil || !ra.r.Registered || ra.r.Payment.AccountID != a ||
295				ra.r.BillBalance != 600 || ra.r.Settled {
296				t.Fatalf("iter %d concurrent a: %+v %v", iter, ra.r, ra.err)
297			}
298			if rb.err != nil || !rb.r.Registered || rb.r.Payment.AccountID != b ||
299				rb.r.BillBalance != 1500 || rb.r.Settled {
300				t.Fatalf("iter %d concurrent b: %+v %v", iter, rb.r, rb.err)
301			}
302			wantAccountBillState(t, s, a, 1000, 400, 600, false)
303			wantAccountBillState(t, s, b, 2000, 500, 1500, false)
304		}
305	}
