	if !cancelRes.Cancelled || !cancelRes.Cancellation.EndAt.Equal(utc(2026, 3, 1, 0, 0)) {
		t.Fatalf("cancel result = %+v, want end 2026-03-01", cancelRes)
	}

	// 三月月初订阅已实际终止：无有效订阅、当前套餐为零值，历史账单仍可查。
	clk.t = utc(2026, 3, 1, 0, 0)
